//--|🠊 Menu.select.tsx 🠈|--\\
//--|🠋 Dependencies 🠋|--\\
import React, { useEffect } from 'react';

//--|🠋 Components 🠋|--\\
import ButtonRouting from '../../Button/routing/Button.routing';

//--|🠋 Functions 🠋|--\\
import { stripBrackets } from '../../../../scripts';
import reloadElements, { modifyControl, selectFullscreen, createClass } from './Menu_select';

interface TheseProps {
  info: {
    pageName: string;
    blockName: string;
    labelName: string;
  };
  style: {
    shade: '~dark~' | '~light~';
    image: string | Array<string>;
    size: '<h1>' | '<h4>' | '<p>' | Array<'<h1>' | '<h4>' | '<p>'>;
    view: 'top-cen' | 'mid-lef' | 'mid-cen' | 'mid-rig' | 'bot-cen';
    color: Array<string> | '(mono)' | '(red)' | '(green)' | '(blue)';
    align: '-top-' | '-rig-' | '-mid-' | '-cen-' | '-bot-' | '-lef-';
  };
  cases: {
    pages: number;
    axis: '[x]' | '[y]';
    link?: Array<string> | undefined;
    task?: Array<() => void> | undefined;
  };

  onClick?: () => void;
  onMouseEnter?: () => void;
}

function MenuSelect({ info, style, cases }: TheseProps) {
  const pageName: string = info.pageName as string;
  const blockName: string = info.blockName as string;
  const labelName: string = info.labelName as string;

  useEffect(() => {
    /*--|🠋

    🠉|--*/
    reloadElements(pageName, blockName, labelName);
    modifyControl(pageName, blockName, labelName, cases.axis);
  }, [pageName, blockName, labelName]);

  let ListStyle = axisList[cases.axis] as React.ElementType;
  return (
    <menu className={`${labelName}-${blockName}_select-default`}>
      <ListStyle className={`${axisClass[cases.axis][0]} ${createClass(cases.axis, style)}`}>
        <li className={`preview-${axisClass[cases.axis][1]}_I`}>
          <MenuAxis info={info} style={style} cases={cases} />
        </li>
      </ListStyle>
    </menu>
  );
}
const MenuAxis: React.FC<TheseProps> = ({ info, style, cases }) => {
  let casesLink: Array<string>;
  if (typeof cases.link === 'object') {
    casesLink = cases.link;
  } else {
    casesLink = Array.from({ length: cases.pages }, () => info.labelName);
  }

  let styleSize: Array<'<h1>' | '<h4>' | '<p>'>;
  if (typeof style.size === 'object') {
    styleSize = style.size;
  } else {
    styleSize = Array.from({ length: cases.pages }, () => style.size as '<h1>' | '<h4>' | '<p>');
  }

  let styleColor: Array<string>;
  if (typeof style.color === 'object') {
    styleColor = style.color;
  } else {
    styleColor = Array.from({ length: cases.pages }, () => style.color as '(mono)' | '(red)' | '(green)' | '(blue)');
  }

  let stateView = 'downplay' as 'downplay' | 'highlight';
  let axisView = axisClass[cases.axis][0].split('-')[0] as 'hori' | 'vert';
  switch (typeof style.image) {
    case 'object':
      return (
        <>
          {Array.from({ length: cases.pages }, (_, index) => (
            <div key={index} className={`${axisView}-view ${stateView}`}>
              <ButtonRouting
                info={{
                  pageName: info.pageName,
                  blockName: info.blockName,
                  labelName: `${casesLink[index]}-select`,
                }}
                style={{
                  image: style.image[index] as string,
                  shade: style.shade as '~dark~' | '~light~',
                  clarity: '⟨lucid⟩',
                  view: style.view as 'top-cen' | 'mid-lef' | 'mid-cen' | 'mid-rig' | 'bot-cen',
                  //--|===|--\\
                  size: styleSize[index] as '<h1>' | '<h4>' | '<p>',
                  color: styleColor[index] as '(mono)' | '(red)' | '(green)' | '(blue)',
                }}
                onClick={(event: React.MouseEvent<HTMLButtonElement>): void => {
                  if (cases.task === undefined) {
                    selectFullscreen(event.currentTarget.parentElement as HTMLDivElement, info.pageName, info.blockName, info.labelName, cases.axis);
                  } else {
                    cases.task[index]();
                  }
                }}
              />
            </div>
          ))}
        </>
      );
    case 'string':
      return (
        <>
          {Array.from({ length: cases.pages }, (_, index) => (
            <div key={index} className={`${axisView}-view ${stateView}`}>
              <ButtonRouting
                info={{
                  pageName: info.pageName,
                  blockName: info.blockName,
                  labelName: `${casesLink[index]}-select`,
                }}
                style={{
                  image: style.image as string,
                  shade: style.shade as '~dark~' | '~light~',
                  clarity: '⟨lucid⟩',
                  view: style.view as 'top-cen' | 'mid-lef' | 'mid-cen' | 'mid-rig' | 'bot-cen',
                  //--|===|--\\
                  size: styleSize[index] as '<h1>' | '<h4>' | '<p>',
                  color: styleColor[index] as '(mono)' | '(red)' | '(green)' | '(blue)',
                }}
                onClick={(event: React.MouseEvent<HTMLButtonElement>): void => {
                  if (cases.task === undefined) {
                    selectFullscreen(event.currentTarget.parentElement as HTMLDivElement, info.pageName, info.blockName, info.labelName, cases.axis);
                  } else {
                    cases.task[index]();
                  }
                }}
              />
            </div>
          ))}
        </>
      );
  }
};
let axisList: Record<'[x]' | '[y]', 'ul' | 'ol'> = {
  '[x]': 'ul',
  '[y]': 'ol',
}; //--|🠈 Wraps with <ul> or <ol> element 🠈|--\\
let axisClass: Record<TheseProps['cases']['axis'], Array<string>> = {
  '[x]': ['hori-X-select', 'horizontal'],
  '[y]': ['vert-Y-select', 'vertical'],
}; //--|🠈 Marks [x] or [y] axis 🠈|--\\

export default MenuSelect;
